// LCS - two-string 2D DP
function lcs(s1, s2) {
  const m = s1.length, n = s2.length;
  // 1-indexed: dp[i][j] = LCS of s1[0..i-1] and s2[0..j-1]
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (s1[i - 1] === s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1; // characters match
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); // skip one char
      }
    }
  }
  return dp[m][n];
}

// 0/1 Knapsack - space-optimized to 1D (iterate weight backward)
function knapsack(weights, values, capacity) {
  const n = weights.length;
  const dp = new Array(capacity + 1).fill(0); // dp[w] = max value at capacity w

  for (let i = 0; i < n; i++) {
    // iterate backward: prevents using item i more than once
    for (let w = capacity; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
    }
  }
  return dp[capacity];
}
